def cache_sim(capacity, ttl, ops):
    cache = OrderedDict()  # key -> [value, expire_time]
    results = []

    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op
            # check if key exists and expired
            if key in cache:
                val, expire = cache[key]
                if t >= expire:
                    # expired, remove it
                    del cache[key]

            if key in cache:
                # update existing, move to end
                cache[key] = [value, t + ttl]
                cache.move_to_end(key)
            else:
                # new key
                if len(cache) >= capacity:
                    # evict LRU
                    cache.popitem(last=False)
                cache[key] = [value, t + ttl]
                cache.move_to_end(key)

        elif op[0] == 'get':
            _, t, key = op
            if key in cache:
                val, expire = cache[key]
                if t >= expire:
                    # expired
                    del cache[key]
                    results.append(-1)
                else:
                    cache.move_to_end(key)
                    results.append(val)
            else:
                results.append(-1)

    return results

